PRAGMA foreign_keys = ON;
CREATE TABLE schools (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, address TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, school_id INTEGER REFERENCES schools(id) ON DELETE CASCADE, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', department TEXT NOT NULL DEFAULT '', subjects TEXT NOT NULL DEFAULT '', responsibilities TEXT NOT NULL DEFAULT '', role TEXT NOT NULL CHECK (role IN ('super_admin', 'admin', 'general')), password_hash TEXT, password_expires_at INTEGER, auth_version INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, CHECK ((role = 'super_admin' AND school_id IS NULL) OR (role IN ('admin', 'general') AND school_id IS NOT NULL)));
CREATE INDEX users_school ON users(school_id);
CREATE TABLE passkeys (id INTEGER PRIMARY KEY AUTOINCREMENT, credential_id TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, public_key TEXT NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, name TEXT NOT NULL, device_type TEXT NOT NULL, backed_up INTEGER NOT NULL, created_at INTEGER NOT NULL, last_used_at INTEGER);
CREATE INDEX passkeys_user ON passkeys(user_id);
CREATE TABLE sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, token_hash TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, scope TEXT NOT NULL CHECK (scope IN ('enroll', 'full')), auth_version INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE challenges (id INTEGER PRIMARY KEY AUTOINCREMENT, token_hash TEXT NOT NULL UNIQUE, challenge TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('registration', 'authentication')), user_id INTEGER REFERENCES users(id) ON DELETE CASCADE, auth_version INTEGER, session_id INTEGER, name TEXT, expires_at INTEGER NOT NULL);
CREATE INDEX challenges_expiry ON challenges(expires_at);
CREATE TABLE auth_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, key_hash TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);